import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"draft":true},"headers":[],"relativePath":"guides/the-manual/about.md","filePath":"guides/the-manual/about.md"}`),a={name:`guides/the-manual/about.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="why-warpdrive" tabindex="-1">Why WarpDrive? <a class="header-anchor" href="#why-warpdrive" aria-label="Permalink to “Why WarpDrive?”">​</a></h2><p>WarpDrive is the data framework for building ambitious applications.</p><p>What do we mean by ambitious? WarpDrive is ideal for applications looking to be best-in-class: whether that&#39;s a small todo app, e-commerce, a social app, or an enterprise b2b software solution.</p><p>That&#39;s because WarpDrive is designed to seamlessly handle the hardest parts of state management when building an app, helping you focus on creating the features and user experiences that drive value.</p><p>At its most basic, it is &quot;managed fetch&quot;. At its most advanced it is a powerful local-first or offline-first solution that dedupes and reactively updates requests across tabs.</p><p>Our value goes beyond our feature set. WarpDrive embraces the platform, making it quick to pickup the basics. Our patterns are portable and scalable, meaning that as your app, team and data needs evolve we&#39;ll be right there with you.</p><p>Usage across various rendering frameworks will be similar. In fact, this is an explicit goal: WarpDrive enables developers to quickly port and re-use data patterns.</p><p>Because we are universal and also not tied to any API Format or backend architecture, there&#39;s no lock-in. The data patterns you learn and the code you write is portable between frontend frameworks and backend APIs and can help smooth the evolution of both.</p><p>We&#39;re also not specific to a given frontend architecture. When serving on the same domain, you can dedupe and cache requests across multiple apps and tabs at once! This means we are as good for embedded content and MPAs as we are for SPAs.</p><p>A single WarpDrive configuration can power multiple web-apps using differing frameworks all sharing a single domain: bridging the gap between MPA and SPA.</p><p>We see this as one of the keys to scalability. Providing a stable framework for how data is requested, cached, mutated, and mocked allows developers to focus more time on the product requirements that matter.</p><p>Our core philosophy is to deliver value that lasts decades and evolves with your app, helping you ship, iterate and deliver to your customers.</p><br><h2 id="a-very-brief-history" tabindex="-1">A Very Brief History <a class="header-anchor" href="#a-very-brief-history" aria-label="Permalink to “A Very Brief History”">​</a></h2><p>WarpDrive began in ~2006 as a suite of ORM-like data utilities in SproutCore that later evolved into EmberData. Beginning in ~2017 the team plotted a course towards a significant evolution of the library based on the lessons learned in the first eleven years.</p><p>In ~2023 we lifted the veil on that work, shifting from a resource-centric library to a request-centric library and began accelerating towards our goal of becoming a universal library prepared for the demands of web applications over the coming decades.</p><br>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};